import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = dirname(fileURLToPath(import.meta.url));
const sourceFiles = [
  "data/model-results.js",
  "data/passengers.js",
  "data/levels.js",
  "data/translations.js",
  "engine/scoring.js",
  "engine/level-manager.js",
  "engine/game-state.js",
  "ui/passenger-panel.js",
  "ui/result-panel.js",
  "ui/model-analysis.js",
  "ui/ship-map.js",
  "game.js",
];

function stripModuleSyntax(source) {
  return source
    .replace(/^import[\s\S]*?from\s+["'][^"']+["'];\s*/gm, "")
    .replace(/\bexport\s+(?=(?:const|function|class)\b)/g, "");
}

const sections = sourceFiles.map((relativePath) => {
  const source = readFileSync(join(root, relativePath), "utf8");
  return `\n// ---- ${relativePath} ----\n${stripModuleSyntax(source).trim()}\n`;
});

const output = [
  "/* Generated by build-bundle.mjs. Edit the modules in data/, engine/, ui/, or game.js. */",
  "(() => {",
  '  "use strict";',
  ...sections,
  "})();",
  "",
].join("\n");

const outputPath = join(root, "game.bundle.js");
if (process.argv.includes("--check")) {
  const current = readFileSync(outputPath, "utf8");
  if (current !== output) {
    console.error("website/game.bundle.js is stale. Run: npm run build --prefix website");
    process.exitCode = 1;
  }
} else {
  writeFileSync(outputPath, output, "utf8");
  console.log("Built website/game.bundle.js");
}
